r);}folderLabel.Text="Сохраняем автоматически: "+downloadDir;await LoadContacts();timer.Start();await Poll();}catch(Exception e){Error(e.Message);}}
    async Task LoadContacts(){string selected=currentPeer==""?initialPeer:currentPeer;var rows=await Call("contacts");contacts.Items.Clear();foreach(var r in rows)contacts.Items.Add(new Contact{ID=Value(r,"peer_id"),Name=Value(r,"name")});for(int i=0;i<contacts.Items.Count;i++)if(((Contact)contacts.Items[i]).ID==selected){contacts.SelectedIndex=i;return;}if(contacts.Items.Count>0)contacts.SelectedIndex=0;}
    async Task AddContact(){using(var d=new Form{Text="Новый контакт",ClientSize=new Size(530,210),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,Font=Font}){var name=new TextBox{Left=20,Top=35,Width=490};var id=new TextBox{Left=20,Top=100,Width=490};d.Controls.Add(new Label{Left=20,Top=12,Text="Имя контакта",AutoSize=true});d.Controls.Add(name);d.Controls.Add(new Label{Left=20,Top=76,Text="Peer ID · для файлов добавьте друг друга",AutoSize=true});d.Controls.Add(id);var ok=new Button{Left=350,Top=155,Width=160,Height=36,Text="Добавить",DialogResult=DialogResult.OK};d.Controls.Add(ok);d.AcceptButton=ok;if(d.ShowDialog(this)!=DialogResult.OK)return;await Call("add-contact",id.Text.Trim(),name.Text.Trim());currentPeer=id.Text.Trim();await LoadContacts();}}
    async Task Poll(){if(polling||!initialized||closing)return;polling=true;try{var s=(await Call("status"))[0];var transfers=s.ContainsKey("transfers")?s["transfers"] as Dictionary<string,object>:null;DateTime now=DateTime.UtcNow;double elapsed=(now-lastRate).TotalSeconds;if(transfers!=null&&elapsed>0){long up=Number(transfers,"uploaded"),down=Number(transfers,"downloaded");totals.Text="↑ "+Bytes(Math.Max(0,up-lastUp)/elapsed)+"/с    ↓ "+Bytes(Math.Max(0,down-lastDown)/elapsed)+"/с     ·     Все передачи";lastUp=up;lastDown=down;lastRate=now;}networkLabel.Text=Value(s,"state")=="online"?"● Сеть готова":"● Подключение к сети…";var routes=s.ContainsKey("routes")?s["routes"] as Dictionary<string,object>:null;if(routes!=null&&routes.ContainsKey(currentPeer)){var r=(Dictionary<string,object>)routes[currentPeer];routeLabel.Text=RouteLabel(Value(r,"route"),Value(r,"stage"));}allFiles=(await Call("files")).Select(Transfer.Read).ToList();RefreshTransfers();await RefreshChat();}catch(Exception e){networkLabel.Text="● Нет связи с ядром";notice.Text=e.Message;}finally{polling=false;}}
    async Task RefreshChat(){if(!initialized||currentPeer==""||closing)return;string selected=currentPeer;try{var rows=await Call("history",selected,"--limit","100");if(currentPeer!=selected||closing)return;string signature=json.Serialize(rows);if(signature==lastHistory)return;lastHistory=signature;history.Clear();foreach(var r in rows){var m=r.ContainsKey("message")?r["message"] as Dictionary<string,object>:null;if(m==null)continue;bool outgoing=Value(r,"direction")=="out";history.SelectionFont=new Font("Segoe UI",9,FontStyle.Bold);history.SelectionColor=outgoing?blue:muted;history.AppendText((outgoing?"Вы":"Собеседник")+"   ·   "+StateLabel(Value(r,"status"))+"\n");history.SelectionFont=new Font("Segoe UI",11);history.SelectionColor=ink;history.AppendText(Value(m,"text")+"\n\n");}history.SelectionStart=history.TextLength;history.ScrollToCaret();}catch(Exception e){notice.Text=e.Message;}}
    void RefreshTransfers(){var rows=allFiles.Where(r=>showAll.Checked||r.Peer==currentPeer).OrderBy(r=>r.State=="delivered"||r.State=="stored"?2:r.State=="paused"?1:0).ThenByDescending(r=>r.Time).ToList();grid.UpdateItems(rows);long size=rows.Sum(r=>r.Size),done=rows.Sum(r=>Math.Min(r.Size,r.Done));int completed=rows.Count(r=>r.State=="stored"||r.State=="delivered"),queued=rows.Count(r=>r.State=="queued");summary.Text=rows.Count==0?"Перетащите файлы / папку сюда или нажмите Ctrl+V":completed+" из "+rows.Count+" готово · "+Bytes(done)+" из "+Bytes(size)+(queued>0?" · В очереди: "+queued:"");tabs.TabPages[1].Text="Файлы и очередь"+(rows.Count>0?" ("+rows.Count+")":"");}
    bool NeedContact(){if(!initialized){Error("Сначала создайте профиль и подключитесь");return false;}if(currentPeer==""){Error("Выберите контакт слева");return false;}return true;}
    async Task SendText(){if(sendingText||!NeedContact()||string.IsNullOrWhiteSpace(input.Text))return;sendingText=true;send.Enabled=false;string text=input.Text,target=currentPeer;try{await CallInput(text,"send",target,"--stdin");input.Clear();await RefreshChat();}catch(Exception e){Error("Доставка не подтверждена — проверьте историю.\n"+e.Message);}finally{sendingText=false;send.Enabled=true;}}
    async Task PickFiles(){if(!NeedContact())return;using(var d=new OpenFileDialog{Title="Выберите файлы · можно сразу много",Multiselect=true})if(d.ShowDialog(this)==DialogResult.OK)await QueueFiles(d.FileNames);}
    async Task PickFolder(){if(!NeedContact())return;using(var d=new FolderBrowserDialog{Description="Все файлы из папки и вложенных папок будут добавлены в очередь"})if(d.ShowDialog(this)==DialogResult.OK)await QueueFiles(new[]{d.SelectedPath});}
    async Task QueueFiles(string[] selection){if(!NeedContact())return;string target=currentPeer;await addGate.WaitAsync();try{tabs.SelectedIndex=1;notice.Text="Собираем файлы…";var errors=new List<string>();string[] paths=await Task.Run(()=>{var found=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var pending=new Stack<string>(selection);while(pending.Count>0){string path=pending.Pop();try{if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)continue;if(File.Exists(path))found.Add(Path.GetFullPath(path));else if(Directory.Exists(path))foreach(var child in Directory.EnumerateFileSystemEntries(path))pending.Push(child);}catch(Exception e){errors.Add(Path.GetFileName(path)+": "+e.Message);}}return found.ToArray();});int added=0;for(int i=0;i<paths.Length;i+=64){var batch=paths.Skip(i).Take(64).ToArray();var results=await CallInput(json.Serialize(batch),"send-files",target,"--stdin");foreach(var r in results){if(Value(r,"error")!="")errors.Add(Value(r,"path")+": "+Value(r,"error"));else added++;}notice.Text="Добавлено "+added+" из "+paths.Length+" · очередь отправляется автоматически";await Poll();}notice.Text="В очередь добавлено файлов: "+added+(errors.Count>0?" · Не добавлено: "+errors.Count:"");if(errors.Count>0)Error(string.Join("\n",errors.Take(8))+(errors.Count>8?"\nИ ещё "+(errors.Count-8)+" ошибок":""));}catch(Exception e){Error("Часть очереди могла быть добавлена. Проверьте список перед повтором.\n"+e.Message);}finally{addGate.Release();}}
    async Task BatchAction(string method){var rows=grid.SelectedTransfers();if(rows.Count==0)rows=grid.Items;var ids=rows.Where(r=>r.Direction=="out"&&r.State!="delivered").Select(r=>r.ID).ToArray();for(int i=0;i<ids.Length;i+=128){var results=await CallInput(json.Serialize(ids.Skip(i).Take(128).ToArray()),method,"--stdin");var errors=results.Where(r=>Value(r,"error")!="").ToList();if(errors.Count>0)notice.Text=errors.Count+" задач не изменены: "+Value(errors[0],"error");}await Poll();}
    async Task ChooseDownloadDir(){if(!initialized)return;using(var d=new FolderBrowserDialog{Description="Папка для автоматического сохранения всех входящих файлов",SelectedPath=downloadDir})if(d.ShowDialog(this)==DialogResult.OK){await Call("download-dir",d.SelectedPath);downloadDir=d.SelectedPath;folderLabel.Text="Сохраняем автоматически: "+downloadDir;}}
    void RevealFile(){var selected=grid.SelectedTransfers().FirstOrDefault();string path=selected==null?downloadDir:(selected.Export!=""?selected.Export:selected.Path);if(string.IsNullOrEmpty(path))return;if(File.Exists(path))Process.Start("explorer.exe","/select,"+Quote(path));else if(Directory.Exists(path))Process.Start(new ProcessStartInfo(path){UseShellExecute=true});else notice.Text="Файл ещё не готов или уже перемещён";}
}
